module EagletonTallest (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire signed [31:0] k,\n    input wire signed [31:0] h0,\n    input wire signed [31:0] h1,\n    input wire signed [31:0] h2,\n    input wire signed [31:0] h3,\n    output reg signed [31:0] result,\n    output reg done\n);\n\n    // State encoding\n    localparam [3:0] IDLE         = 4'd0;\n    localparam [3:0] START_SCAN   = 4'd1;\n    localparam [3:0] CHECK_HOUSE  = 4'd2;\n    localparam [3:0] UPDATE_HOUSE = 4'd3;\n    localparam [3:0] NEXT_HOUSE   = 4'd4;\n    localparam [3:0] SCAN_DONE    = 4'd5;\n    localparam [3:0] MAX_COMPUTE  = 4'd6;\n    localparam [3:0] OUTPUT       = 4'd7;\n\n    reg [3:0] state;\n    reg [3:0] i;\n    reg signed [31:0] heights [0:3];\n    reg changed;\n    reg [9:0] iteration_counter;\n    reg signed [31:0] target;\n\n    // Fixed-point division by 2 (arithmetic shift right)\n    function signed [31:0] div2;\n        input signed [31:0] x;\n        begin\n            div2 = {x[31], x[31:1]};\n        end\n    endfunction\n\n    integer idx;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            i <= 4'd0;\n            changed <= 1'b0;\n            iteration_counter <= 10'd0;\n            for (idx = 0; idx < 4; idx = idx + 1) begin\n                heights[idx] <= 32'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Load initial heights based on N\n                        if (N >= 4'd1) heights[0] <= h0;\n                        if (N >= 4'd2) begin\n                            heights[1] <= h1;\n                        end\n                        if (N >= 4'd3) begin\n                            heights[2] <= h2;\n                        end\n                        if (N >= 4'd4) begin\n                            heights[3] <= h3;\n                        end\n                        i <= 4'd0;\n                        changed <= 1'b0;\n                        iteration_counter <= 10'd0;\n                        state <= START_SCAN;\n                    end\n                end\n\n                START_SCAN: begin\n                    i <= 4'd0;\n                    changed <= 1'b0;\n                    state <= CHECK_HOUSE;\n                end\n\n                CHECK_HOUSE: begin\n                    // Get neighbor heights (0 if out of bounds)\n                    automatic logic signed [31:0] left_neighbor = (i == 4'd0) ? 32'sd0 : heights[i-1];\n                    automatic logic signed [31:0] right_neighbor = (i >= (N-4'd1)) ? 32'sd0 : heights[i+1];\n                    target <= div2(left_neighbor + right_neighbor) + k;\n                    state <= UPDATE_HOUSE;\n                end\n\n                UPDATE_HOUSE: begin\n                    if (heights[i] < target) begin\n                        heights[i] <= target;\n                        changed <= 1'b1;\n                    end\n                    state <= NEXT_HOUSE;\n                end\n\n                NEXT_HOUSE: begin\n                    if (i < (N-4'd1)) begin\n                        i <= i + 4'd1;\n                        state <= CHECK_HOUSE;\n                    end else begin\n                        state <= SCAN_DONE;\n                    end\n                end\n\n                SCAN_DONE: begin\n                    if (changed) begin\n                        iteration_counter <= iteration_counter + 10'd1;\n                        if (iteration_counter < 10'd1000) begin\n                            state <= START_SCAN;\n                        end else begin\n                            state <= MAX_COMPUTE;\n                        end\n                    end else begin\n                        state <= MAX_COMPUTE;\n                    end\n                end\n\n                MAX_COMPUTE: begin\n                    // Find maximum height among N houses\n                    result <= heights[0];\n                    if (N >= 4'd2 && heights[1] > result) result <= heights[1];\n                    if (N >= 4'd3 && heights[2] > result) result <= heights[2];\n                    if (N == 4'd4 && heights[3] > result) result <= heights[3];\n                    state <= OUTPUT;\n                end\n\n                OUTPUT: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule